function consumeAudio(events:any[],session:string){if(!audioEnabled||!questAudio)return;for(const e of events||[]){const key=session+':'+(e.dedupeKey||e.sequence);if(heardAudio.has(key))continue;heardAudio.add(key);sourceAudioQueue=sourceAudioQueue.then(async()=>{if(!audioEnabled||!questAudio)return;const slot=e.objectId||'music';if(e.command==='play'&&Number.isInteger(e.number)&&e.number>0){questAudio.setSlotVolume(slot,(e.volume??127)/127);await questAudio.play(e.number,{slot,loop:e.loop===-1});}else if(['stop','dispose'].includes(e.command))questAudio.stop(slot);else if(e.command==='pause'){if(e.arguments?.[0]===0)questAudio.resume(slot);else questAudio.pause(slot);}else if(e.command==='resume')questAudio.resume(slot);else if(['vol','setVol','volume'].includes(e.command)&&Number.isFinite(e.volume))questAudio.setSlotVolume(slot,e.volume/127);else if(e.command==='fade'){const args=e.arguments||[],to=args[0]??0,ticks=args[1]??25,step=args[2]??10,stop=args[3]??1;questAudio.fade(slot,to/127,Math.ceil(Math.abs((e.volume??127)-to)/Math.max(1,step))*Math.max(1,ticks)*1000/60,{stopWhenSilent:!!stop&&to===0});}}).catch(e=>console.warn('Source audio',e));}}
