 if(artMode==='modern'){const hidden=new Set<string>();for(const [key,c]of Object.entries(art.characters||{}))if(c.room===state.room&&actorVisible(c)&&drawables.some((d:any)=>d.entityId===(c.entityId||key)))for(const part of c.hiddenPartEntityIds||[])hidden.add(part);drawables=drawables.filter((d:any)=>!hidden.has(d.entityId));}
