function itemName(id:string){return campaign.items.find(i=>i.id===id)?.name||title(id)}
function atlasIcon(a:any,size=36){if(!a)return '';const f=a.frame,scale=Math.min(size/f.w,size/f.h);return `<span aria-hidden="true" class="item-icon" style="width:${size}px;height:${size}px;flex-basis:${size}px"><img alt="" draggable="false" src="${esc(a.url)}" style="width:${a.atlasWidth*scale}px;height:${a.atlasHeight*scale}px;left:${(size-f.w*scale)/2-f.x*scale}px;top:${(size-f.h*scale)/2-f.y*scale}px"></span>`;}
function referenceIcon(url:string){return url?`<span aria-hidden="true" class="item-icon"><img alt="" draggable="false" src="${esc(url)}" class="reference-icon"></span>`:'';}
function itemIcon(id:string){const modern=artMode==='modern'?art.inventoryIcons?.[id]:null;if(modern)return atlasIcon(modern);const item=source.inventory?.find((i:any)=>i.id===id),p=item?.properties,frame=p&&referenceAssets.views?.[p.view??950]?.loops?.[p.loop??0]?.cels?.[p.cel??0];return referenceIcon(frame?.url);}
function spellIcon(id:string){const modern=art.spellIcons?.[id];if(artMode==='modern'&&modern)return atlasIcon(modern);const spell=source.spells?.find((i:any)=>i.id===id),p=spell?.properties,frame=p&&referenceAssets.views?.[p.view??992]?.loops?.[p.loop??0]?.cels?.[p.cel??0];return referenceIcon(modern?.sourceIcon?.url||frame?.url);}
