 const el=showSceneDialog(`<div class="eyebrow">A conversation in Spielburg</div><h2>${esc(charName(character.entityId,character.name))}</h2><p class="dialogue-location">${esc(path.length?path.join(' › '):'Choose a subject')}</p><div class="dialogue-layout"><div class="topic-list">${path.length?'<button id="topic-back">← Back</button>':''}${trading?offerButtons(offers):branch.map(e=>`<button data-topic="${esc(e.topic.id)}">${esc(e.topic.label)}${e.hasChildren?' ›':''}</button>`).join('')}${!path.length?npcServices.map((a,i)=>`<button data-npc-service="${i}">${esc(a.label||a.type)}</button>`).join(''):''}${!path.length&&offers.length?'<button id="topic-trade">Buy / trade ›</button>':''}</div><div class="dialogue-lines">${portraitMarkup}${reading?reading.lines.slice(linePage,linePage+1).map((l,j)=>{const i=linePage+j;return `<div class="dialogue-line"><small>${esc(l.speaker===character.name?charName(character.entityId,character.name):l.speaker||character.name)}</small><p>${esc(overrides.overrides.dialogue[characterId+':'+selectedTopic+':'+i]?.text||l.text)}</p></div>`}).join(''):`<p>${esc(lookAt(state,dialogueData,characterId).map(l=>l.text).join(' ')||'What would you like to ask?')}</p>`}${!trading&&topicOffers.length?'<div class="dialogue-offers">'+offerButtons(topicOffers)+'</div>':''}</div></div>${reading&&reading.lines.length>1?`<div class="reply-pages">${linePage?'<button id="reply-prev">← Previous</button>':''}<small>${linePage+1} / ${reading.lines.length}</small>${linePage+1<reading.lines.length?'<button id="reply-next">Next →</button>':''}</div>`:''}<p>${state.gold} gold · ${state.silver} silver</p><button id="close-conversation" class="primary">Back to adventure</button>`);
