 el.querySelectorAll('[data-topic]').forEach(b=>b.addEventListener('click',()=>{if(state.room!==ownerRoom)return el.remove();const id=(b as HTMLElement).dataset.topic!,topic=readTopic(state,dialogueData,characterId,id);if(!topic)return;const next=topicHasChildren(state,dialogueData,characterId,branch.find(e=>e.topic.id===id)!.topic,path)?[...path,topic.label]:path;transact({type:'dialogue',target:character.entityId,topic:id});const beforeServiceSerial=state.stats.innServiceSerial;if(topic.nativeAction&&actionAvailable(topic.nativeAction))transact(topic.nativeAction);if(state.stats.innServiceSerial!==beforeServiceSerial&&innServiceFor(state)?.phase==='ordered'){el.remove();return;}if(state.room!==ownerRoom){el.remove();return;}say(...topic.lines.map((l,i)=>overrides.overrides.dialogue[characterId+':'+id+':'+i]?.text||l.text));el.remove();showConversation(characterId,id,topic,next);}));
