 const boxWidth=Math.min(660,width-16),boxHeight=Math.min(420,Math.max(170,height-64)),left=Math.max(8,Math.min(width-boxWidth-8,(scene?.right||width)-boxWidth)),top=Math.max(8,Math.min(height-boxHeight-12,(scene?.bottom||height)-80));
 el.style.setProperty('--dialog-left',left+'px');el.style.setProperty('--dialog-top',top+'px');el.style.setProperty('--dialog-width',boxWidth+'px');el.style.setProperty('--dialog-max-height',boxHeight+'px');
