function installPlayLayout(){playResizeObserver?.disconnect();playResizeObserver=new ResizeObserver(queuePlayLayout);for(const selector of ['.player-stage','#player-context','#player-status','.action-toolbar']){const el=document.querySelector(selector);if(el)playResizeObserver.observe(el)}queuePlayLayout()}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state?.combat?.clock)state.combat.clock.paused=true;});
