function showCharacter(){const el=showModal(`<div class="eyebrow">${esc(state.heroClass)}</div><h2>${esc(state.heroName)}</h2><p>Unassigned ability points: <b>${state.stats.unspent||0}</b></p><div style="display:grid;grid-template-columns:1fr 1fr;gap:5px">${['strength','agility','vitality','intelligence','luck','weaponUse','parry','dodge','stealth','climbing','throwing','pickLocks','magic'].map(k=>`<button data-skill="${k}" style="display:flex;justify-content:space-between">${title(k)} <b>${state.stats[k]||0}${state.stats.unspent?' +':''}</b></button>`).join('')}</div><button id="close-sheet" class="primary" style="margin-top:20px">Return to adventure</button>`);el.querySelectorAll('[data-skill]').forEach(b=>b.addEventListener('click',()=>{if(!state.stats.unspent)return;transact({type:'allocate',target:(b as HTMLElement).dataset.skill,amount:Math.min(5,state.stats.unspent)});el.remove();showCharacter()}));$('#close-sheet').addEventListener('click',()=>el.remove())}
function showSpells(){if(!state.spells?.length){say('You have not learned any spells.');return}const el=showModal(`<div class="eyebrow">The art of magic</div><h2>Your spellbook</h2><div class="action-list">${state.spells.map(id=>`<button data-spell="${id}">${spellIcon(id)}<span>${esc(campaign.spells.find(s=>s.id===id)?.name||id)}</span></button>`).join('')}</div><p style="margin-top:18px">Select a spell, then a target. In combat, spells follow their casting time.</p><button id="close-spells">Close</button>`);el.querySelectorAll('[data-spell]').forEach(b=>b.addEventListener('click',()=>{const spell=(b as HTMLElement).dataset.spell!;selectedItem=spell;verb='cast';el.remove();if(state.combat)transact({type:'cast',spell});else say(`Ready to cast ${campaign.spells.find(s=>s.id===spell)?.name||spell}. Select its target.`)}));$('#close-spells').addEventListener('click',()=>el.remove())}
