  drawCombat(){this.add.rectangle(720,540,1440,1080,0x0c1719,.48);this.add.text(720,100,state.combat!.name,{fontFamily:'Georgia',fontSize:'43px',color:'#efe1bd'}).setOrigin(.5);this.add.text(720,158,supportsLiveCombat(state)?'Live combat · watch his guard and time your defense':'Turn combat · Attack · Parry · Dodge · Cast · Flee',{fontFamily:'Georgia',fontSize:'23px',color:'#becbbb'}).setOrigin(.5);this.add.ellipse(440,900,240,45,0x07110c,.6);this.add.ellipse(1000,900,250,45,0x07110c,.6);this.hero=this.add.sprite(440,900,'hero-combat',0).setOrigin(.5,1).setDisplaySize(470,476).setDepth(900);const modern=this.modernEnemy();const f=this.enemyFrame();if(modern&&this.textures.exists('enemy-'+modern.entityId)){this.enemy=this.add.sprite(1000,900,'enemy-'+modern.entityId,'pose0').setOrigin(modern.anchorX/modern.frameWidth,modern.anchorY/modern.frameHeight).setScale(550/(modern.anchorY||570));}else if(f&&this.textures.exists(f.url)){this.enemy=this.add.image(1000,900,f.url).setOrigin(.5,1);const scale=Math.min(600/f.height,430/f.width);this.enemy.setDisplaySize(f.width*scale,f.height*scale)}this.combatEnemyText=this.add.text(1000,300,`${state.combat!.health} / ${state.combat!.maxHealth} HP`,{fontSize:'25px',color:'#ecd7b0'}).setOrigin(.5);this.combatHeroText=this.add.text(440,960,`${state.heroName} · ${state.stats.health} HP · ${state.combat?.heroStamina??state.stats.stamina} SP`,{fontSize:'24px',color:'#dfebcf'}).setOrigin(.5)}
