  drawMinigame(){const g=state.minigame!;this.add.rectangle(720,540,1320,940,0x102329,.9).setStrokeStyle(2,0xc2b889);this.add.text(720,120,g.kind==='maze'?'Mage’s Maze':'Dag-Nab-It',{fontFamily:'Georgia',fontSize:'45px',color:'#f0dfb8'}).setOrigin(.5);if(g.kind==='maze'){const grid=this.add.graphics();grid.lineStyle(2,0x718a6e,.5);for(let row=0;row<10;row++)grid.lineBetween(180,260+row*65,1260,260+row*65);for(let col=0;col<15;col++)grid.lineBetween(180+col*75,260,180+col*75,845);for(const o of g.obstacles||[]){if(o.cleared)continue;const x=180+(o.x/320)*1080,y=260+(o.y/190)*580;this.add.circle(x,y,22,o.kind==='rock'?0x8f9177:o.kind==='bridge'?0x966d43:0xd7bd7a);this.add.text(x,y-30,o.kind,{fontSize:'18px',color:'#ede2c0'}).setOrigin(.5)}this.add.circle(205+g.player*75,840,18,0xd6e99c).setStrokeStyle(3,0x4d713a);this.add.circle(205+g.opponent*75,285,18,0xd49065).setStrokeStyle(3,0x714a31);this.add.text(720,940,`Your bug ${g.player}/13 · Erasmus ${g.opponent}/13`,{fontSize:'27px',color:'#dfdfbf'}).setOrigin(.5)}else{const gfx=this.add.graphics();for(let i=5;i>0;i--){gfx.fillStyle(i%2?0xbba16e:0x4c6657);gfx.fillCircle(750,530,i*60)}gfx.fillStyle(0xc77651);gfx.fillCircle(750,530,20);this.add.text(720,915,`Throw ${g.round+1}/9 · Your score ${g.player} · Opponent ${g.opponent}`,{fontSize:'28px',color:'#e2d8b8'}).setOrigin(.5);this.add.text(720,975,`Force ${g.force} / 11 · Angle ${g.angle} / 14`,{fontSize:'23px',color:'#c0d4bb'}).setOrigin(.5)}this.hero=undefined;this.shadow=undefined;}
  drawFallback(r:SourceRoom){const g=this.add.graphics();const town=r.id>=300&&r.id<=340;g.fillGradientStyle(town?0x7e9481:0x45615a,town?0x567968:0x284c43,0x243f33,0x324b36,1);g.fillRect(0,0,1440,1080);g.fillStyle(0x9c9d72,.6);g.fillTriangle(650,360,1000,1080,350,1080);if(town){for(let i=0;i<5;i++){const x=i*340-100;g.fillStyle(i%2?0xa9a38a:0xc3b998);g.fillRect(x,250+60*(i%2),280,440);g.fillStyle(0x554e3a);g.fillTriangle(x-20,280+60*(i%2),x+140,110+60*(i%2),x+300,280+60*(i%2));g.fillStyle(0x263b32);g.fillRect(x+100,490,65,200);}}else{for(let i=0;i<20;i++){const x=(i*193)%1480-20;g.fillStyle(i%2?0x213f31:0x31513b,.85);g.fillRect(x,80,35,650);g.fillEllipse(x+20,130+(i%3)*80,350,490)}}this.add.text(45,38,r.name,{fontFamily:'Georgia',fontSize:'28px',color:'#f1e8c9'});this.add.text(45,80,'Source layout preview · painting pending',{fontSize:'15px',color:'#c3cdb4'});}
  onArrival?:()=>void;
  walkTo(x:number,y:number,arrive?:()=>void){if(!this.hero||state.dead||![x,y,this.hero.x,this.hero.y].every(Number.isFinite))return;this.onArrival=undefined;this.target=undefined;this.waypoints=[];const target={x:Phaser.Math.Clamp(x,35,1405),y:Phaser.Math.Clamp(y,120,1072)};if(!this.walkable(target.x,target.y)){if(arrive){const safe=this.nearestWalkable(target);target.x=safe.x;target.y=safe.y}else{say('You cannot walk there.');return}}const pathBegin=performance.now();this.game.canvas.dataset.pathRequest=JSON.stringify({start:{x:this.hero.x,y:this.hero.y},target});this.waypoints=this.findPath({x:this.hero.x,y:this.hero.y},target);this.game.canvas.dataset.pathMs=String(performance.now()-pathBegin);if(!this.waypoints.length){say('There is no clear path to that spot.');return}this.target=this.waypoints.shift();this.onArrival=arrive;this.faceTarget()}
